import { GEO } from './geodata.js';

// js/city-config.js
// Poznań spatial configuration & street database at true 1:1 scale, derived from the real geography in js/geodata.js
// (generated by tools/build-poznan.mjs from OpenStreetMap).
//
// World frame: 1 unit = 1 m, x = east, z = south (north = -z), origin at the Ratusz on Stary Rynek; the axes are not
// turned (GEO.frame.bearingDeg = 0), so Poznań's many street grids all sit at their own angles. The detailed core
// (GEO.frame.detailBox: Jeżyce, Łazarz, Wilda, Centrum, Stare Miasto, Ostrów Tumski, Śródka, Malta) is land cut by the
// Warta and the Cybina; the low-detail outskirts around it run out to the city boundary (outskirts.js).

const toPts = (flat) => {
  const out = [];
  for (let i = 0; i < flat.length; i += 2) out.push({ x: flat[i], z: flat[i + 1] });
  return out;
};
const [DBX0, DBX1, DBZ0, DBZ1] = GEO.frame.detailBox;
// lon/lat -> world through the build's own affine (GEO.frame.ll): x = a·lon + b·lat + c, z = d·lon + e·lat + f
const [LLA, LLB, LLC, LLD, LLE, LLF] = GEO.frame.ll;
const LL = (lon, lat) => ({ x: LLA * lon + LLB * lat + LLC, z: LLD * lon + LLE * lat + LLF });

function pointInPoly(poly, x, z) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const a = poly[i], b = poly[j];
    if ((a.z > z) !== (b.z > z) && x < ((b.x - a.x) * (z - a.z)) / (b.z - a.z) + a.x) inside = !inside;
  }
  return inside;
}

// ---------------------------------------------------------------------------------------------------------------------
// Land, water, outskirts, rail, plazas & districts, as {x, z} rings
// ---------------------------------------------------------------------------------------------------------------------
/** Land components inside the detail box (west bank, east bank & Śródka, Ostrów Tumski), largest first */
const LAND_RINGS = GEO.land.map(toPts);
/** Water fully enclosed by a land component (ponds): [{ outer: index into LAND_RINGS, ring }] */
const LAND_HOLES = GEO.landHoles.map((h) => ({ outer: h.outer, ring: toPts(h.ring) }));
/** Rivers, lakes, canals & ponds: [{ name, kind: 'river'|'lake'|'canal'|'pond', ring, holes }] (holes are islands) */
const WATER = GEO.water.map((w) => ({ name: w.name, kind: w.kind, ring: toPts(w.ring), holes: (w.holes || []).map(toPts) }));
/** Low-detail land from the detail box out to the city boundary, and the lakes in it ([{ outer, ring }]) */
const OUTSKIRTS = GEO.outskirts.map(toPts);
const OUTSKIRTS_HOLES = GEO.outskirtsHoles.map((h) => ({ outer: h.outer, ring: toPts(h.ring) }));
/** Tram & rail track centrelines: [{ kind: 'tram'|'rail', street: 1 if street-running, tracks, pts }] */
const RAIL = GEO.rail.map((r) => ({ kind: r.kind, street: r.street, tracks: r.tracks, pts: toPts(r.pts) }));
/** Pedestrian areas & squares: [{ name, ring, holes }] (holes are the buildings standing on them) */
const PLAZAS = GEO.plazas.map((p) => ({ name: p.name, ring: toPts(p.ring), holes: (p.holes || []).map(toPts) }));
/** Osiedla (OSM admin_level 9): [{ name, ring, minX, maxX, minZ, maxZ }] */
const DISTRICTS = GEO.districts.map((d) => {
  const ring = toPts(d.ring);
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
  for (const p of ring) {
    minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
  }
  return { name: d.name, ring, minX, maxX, minZ, maxZ };
});

// ---------------------------------------------------------------------------------------------------------------------
// Bridges: the road-graph links flagged as bridges (GEO.roadGraph flags bit 0), chained per name. Decks sit at street
// level (y = 0) and are drivable and walkable; the river runs CITY_BOUNDS.waterLevel below (docs/poznan-plan.md D7).
// ---------------------------------------------------------------------------------------------------------------------
const BRIDGES = (() => {
  const g = GEO.roadGraph;
  const node = (i) => ({ x: g.nodes[i * 2], z: g.nodes[i * 2 + 1] });
  const byName = new Map();
  for (const [a, b, ni, w, lanes, dir, inner, flags] of g.links) {
    if (!(flags & 1)) continue;
    const name = g.names[ni] || '';
    const pts = [node(a), ...toPts(inner || []), node(b)];
    if (!byName.has(name)) byName.set(name, []);
    byName.get(name).push({ pts, width: w, lanes, dir, tram: !!(flags & 2) });
  }
  return [...byName].map(([name, links]) => ({ name, links }));
})();

// ---------------------------------------------------------------------------------------------------------------------
// The extent of the detailed land. waterLevel: the Warta runs ~3 m below the street-level bridge decks.
// ---------------------------------------------------------------------------------------------------------------------
const CITY_BOUNDS = { minX: DBX0, maxX: DBX1, minZ: DBZ0, maxZ: DBZ1, sidewalkHeight: 0.22, waterLevel: -3.0 };

// ---------------------------------------------------------------------------------------------------------------------
// Land / water raster: 2 m cells over the detail box. Code 0 water (or a pond hole), 1 land, 2 bridge deck (the bridge
// links' corridors, carried 15 m past each end so abutments join the land). DIST is each cell's distance to the nearest
// water cell in metres (8-neighbour chamfer, capped at 255), with deck cells pinned to 255: the shore margins callers
// ask for apply along the banks but never narrow a bridge, so the controllers' 8 m shore clamp still lets cars across.
// Outside the box is neither land nor water. ~1.4 M cells, ~40 ms at boot.
// ---------------------------------------------------------------------------------------------------------------------
const LAND_RES = 2;
const LAND_W = Math.ceil((DBX1 - DBX0) / LAND_RES);
const LAND_H = Math.ceil((DBZ1 - DBZ0) / LAND_RES);
const LAND_CODE = new Uint8Array(LAND_W * LAND_H);
const LAND_DIST = new Uint8Array(LAND_W * LAND_H);
(() => {
  // even-odd scanline fill of one ring at the cell centres
  const fill = (ring, v) => {
    const xs = [];
    for (let j = 0; j < LAND_H; j++) {
      const z = DBZ0 + (j + 0.5) * LAND_RES;
      xs.length = 0;
      for (let i = 0, k = ring.length - 1; i < ring.length; k = i++) {
        const a = ring[i], b = ring[k];
        if ((a.z > z) !== (b.z > z)) xs.push(a.x + ((z - a.z) * (b.x - a.x)) / (b.z - a.z));
      }
      if (!xs.length) continue;
      xs.sort((p, q) => p - q);
      for (let n = 0; n + 1 < xs.length; n += 2) {
        const i0 = Math.max(0, Math.ceil((xs[n] - DBX0) / LAND_RES - 0.5));
        const i1 = Math.min(LAND_W - 1, Math.floor((xs[n + 1] - DBX0) / LAND_RES - 0.5));
        for (let i = i0; i <= i1; i++) LAND_CODE[j * LAND_W + i] = v;
      }
    }
  };
  for (const r of LAND_RINGS) fill(r, 1);
  for (const h of LAND_HOLES) fill(h.ring, 0);
  // bridge decks: capsules of half-width w/2 + 2 m along each link, extended 15 m past both ends
  for (const br of BRIDGES) {
    for (const l of br.links) {
      const hw = l.width * 0.5 + 2;
      for (let s = 0; s + 1 < l.pts.length; s++) {
        let a = l.pts[s], b = l.pts[s + 1];
        const len = Math.hypot(b.x - a.x, b.z - a.z) || 1;
        const ux = (b.x - a.x) / len, uz = (b.z - a.z) / len;
        if (s === 0) a = { x: a.x - ux * 15, z: a.z - uz * 15 };
        if (s + 2 === l.pts.length) b = { x: b.x + ux * 15, z: b.z + uz * 15 };
        const dx = b.x - a.x, dz = b.z - a.z, L2 = dx * dx + dz * dz || 1e-9;
        const i0 = Math.max(0, Math.floor((Math.min(a.x, b.x) - hw - DBX0) / LAND_RES));
        const i1 = Math.min(LAND_W - 1, Math.ceil((Math.max(a.x, b.x) + hw - DBX0) / LAND_RES));
        const j0 = Math.max(0, Math.floor((Math.min(a.z, b.z) - hw - DBZ0) / LAND_RES));
        const j1 = Math.min(LAND_H - 1, Math.ceil((Math.max(a.z, b.z) + hw - DBZ0) / LAND_RES));
        for (let j = j0; j <= j1; j++) {
          const z = DBZ0 + (j + 0.5) * LAND_RES;
          for (let i = i0; i <= i1; i++) {
            const x = DBX0 + (i + 0.5) * LAND_RES;
            const t = Math.max(0, Math.min(1, ((x - a.x) * dx + (z - a.z) * dz) / L2));
            if (Math.hypot(a.x + t * dx - x, a.z + t * dz - z) <= hw) LAND_CODE[j * LAND_W + i] = 2;
          }
        }
      }
    }
  }
  // chamfer distance to water (2 m orthogonal, 2.83 m diagonal steps), in metres
  const D = new Float32Array(LAND_W * LAND_H);
  for (let k = 0; k < D.length; k++) D[k] = LAND_CODE[k] === 0 ? 0 : 1e9;
  const o = LAND_RES, d = LAND_RES * Math.SQRT2;
  for (let j = 0; j < LAND_H; j++) {
    for (let i = 0; i < LAND_W; i++) {
      const k = j * LAND_W + i;
      let v = D[k];
      if (!v) continue;
      if (i > 0) v = Math.min(v, D[k - 1] + o);
      if (j > 0) {
        v = Math.min(v, D[k - LAND_W] + o);
        if (i > 0) v = Math.min(v, D[k - LAND_W - 1] + d);
        if (i + 1 < LAND_W) v = Math.min(v, D[k - LAND_W + 1] + d);
      }
      D[k] = v;
    }
  }
  for (let j = LAND_H - 1; j >= 0; j--) {
    for (let i = LAND_W - 1; i >= 0; i--) {
      const k = j * LAND_W + i;
      let v = D[k];
      if (!v) continue;
      if (i + 1 < LAND_W) v = Math.min(v, D[k + 1] + o);
      if (j + 1 < LAND_H) {
        v = Math.min(v, D[k + LAND_W] + o);
        if (i + 1 < LAND_W) v = Math.min(v, D[k + LAND_W + 1] + d);
        if (i > 0) v = Math.min(v, D[k + LAND_W - 1] + d);
      }
      D[k] = v;
    }
  }
  for (let k = 0; k < D.length; k++) LAND_DIST[k] = LAND_CODE[k] === 2 ? 255 : Math.min(255, Math.round(D[k]));
})();
const landCell = (x, z) => {
  const i = Math.floor((x - DBX0) / LAND_RES), j = Math.floor((z - DBZ0) / LAND_RES);
  return i < 0 || j < 0 || i >= LAND_W || j >= LAND_H ? -1 : j * LAND_W + i;
};

/** Is (x, z) ground you can stand on at street level (land or a bridge deck), at least `margin` metres from water? */
function isLand(x, z, margin = 0) {
  const k = landCell(x, z);
  return k >= 0 && LAND_CODE[k] !== 0 && LAND_DIST[k] >= margin;
}

/** Is (x, z) open water inside the detail box (a bridge deck over the river is not)? */
function isWater(x, z) {
  const k = landCell(x, z);
  return k >= 0 && LAND_CODE[k] === 0;
}

/** Distance from (x, z) to the nearest water in metres (0 in the water, 255 on a deck or ≥ 255 m away; 2 m cells) */
function distToWater(x, z) {
  const k = landCell(x, z);
  return k < 0 ? 255 : LAND_DIST[k];
}

/**
 * The nearest point at least `margin` from the water (the input itself when it already is): the centre of the nearest
 * qualifying 2 m cell, searched in growing square rings out to 400 m, clamped into the detail box first. Always returns
 * a point; callers that need the margin check isLand on the result.
 */
function clampToLand(x, z, margin = 0) {
  const cx = Math.max(DBX0 + 1, Math.min(DBX1 - 1, x));
  const cz = Math.max(DBZ0 + 1, Math.min(DBZ1 - 1, z));
  if (isLand(cx, cz, margin)) return { x: cx, z: cz };
  const i0 = Math.floor((cx - DBX0) / LAND_RES), j0 = Math.floor((cz - DBZ0) / LAND_RES);
  for (let r = 1; r <= 200; r++) {
    let best = -1, bestD = Infinity;
    for (let j = j0 - r; j <= j0 + r; j++) {
      if (j < 0 || j >= LAND_H) continue;
      const edge = j === j0 - r || j === j0 + r;
      for (let i = i0 - r; i <= i0 + r; i += edge ? 1 : 2 * r) {
        if (i < 0 || i >= LAND_W) continue;
        const k = j * LAND_W + i;
        if (LAND_CODE[k] === 0 || LAND_DIST[k] < margin) continue;
        const d = (i - i0) * (i - i0) + (j - j0) * (j - j0);
        if (d < bestD) { bestD = d; best = k; }
      }
    }
    if (best >= 0) {
      const i = best % LAND_W, j = (best - i) / LAND_W;
      return { x: DBX0 + (i + 0.5) * LAND_RES, z: DBZ0 + (j + 0.5) * LAND_RES };
    }
  }
  return { x: cx, z: cz };
}

/** The water body under (x, z) (the first WATER entry containing it), or null */
function waterAt(x, z) {
  for (const w of WATER) {
    if (!pointInPoly(w.ring, x, z)) continue;
    if (w.holes.some((h) => pointInPoly(h, x, z))) continue;
    return w;
  }
  return null;
}

// ---------------------------------------------------------------------------------------------------------------------
// Streets: GEO.roadGraph covers the whole core (docs/poznan-plan.md D5); there is no avenue x street grid.
// ---------------------------------------------------------------------------------------------------------------------
// Signalised junctions: the one list both road-network.js (node.signal) and street-details.js (signal heads) read,
// since street details are built before the road network exists. Each site is a junction centre (x, z) plus the widest
// incident road running mostly north-south (nsWidth, signal group 0 on an axis-aligned junction) and east-west
// (ewWidth), which place the corner masts.
const SIGNAL_SITES = (() => {
  const g = GEO.roadGraph;
  const ns = new Map(), ew = new Map();
  for (const [a, b, , w, , , inner] of g.links) {
    for (const [n, m] of [[a, inner && inner.length ? -1 : b], [b, inner && inner.length ? -2 : a]]) {
      // the arm's first leg: towards the other end, or the nearest inner point on a bent link
      let ox, oz;
      if (m === -1) { ox = inner[0]; oz = inner[1]; } else if (m === -2) { ox = inner[inner.length - 2]; oz = inner[inner.length - 1]; } else { ox = g.nodes[m * 2]; oz = g.nodes[m * 2 + 1]; }
      const dx = ox - g.nodes[n * 2], dz = oz - g.nodes[n * 2 + 1];
      const map = Math.abs(dz) >= Math.abs(dx) ? ns : ew;
      map.set(n, Math.max(map.get(n) || 0, w));
    }
  }
  return g.signals.map((n) => ({ x: g.nodes[n * 2], z: g.nodes[n * 2 + 1], nsWidth: ns.get(n) || 0, ewWidth: ew.get(n) || 0 }));
})();

// Named roads (the real centreline, merged per street) — maps, labels & lookups. dir: 1 one-way along pts, -1 against,
// 0 both ways. Names are as signed, without the "ul." prefix (OSM convention).
const ROADS = GEO.roads.map(([name, w, dir, lanes, hw, flat]) => ({ name, raw: name, w, dir, lanes, highway: !!hw, pts: toPts(flat) }));

// Map names (GEO.labels: [{ name, kind: 'suburb'|'quarter'|'neighbourhood'|'water', x, z }]) as the map's
// [[name, x, z, kind]] with kinds 0 district, 1 water, 2 neighbourhood; the map upper-cases them for display
const LABEL_KIND = { suburb: 0, water: 1, quarter: 2, neighbourhood: 2 };
const AREA_LABELS = GEO.labels.map((l) => [l.name, l.x, l.z, LABEL_KIND[l.kind] ?? 2]);
// Shorter map names for a few real street names
const LABEL_ALIAS = {};

// Nearest-road index (labels, sidewalk tests): uniform grid of road segments
const ROAD_CELL = 64;
const ROAD_GRID = new Map();
for (const r of ROADS) {
  for (let i = 0; i + 1 < r.pts.length; i++) {
    const a = r.pts[i];
    const b = r.pts[i + 1];
    const seg = { r, ax: a.x, az: a.z, bx: b.x, bz: b.z };
    const ix0 = Math.floor(Math.min(a.x, b.x) / ROAD_CELL), ix1 = Math.floor(Math.max(a.x, b.x) / ROAD_CELL);
    const iz0 = Math.floor(Math.min(a.z, b.z) / ROAD_CELL), iz1 = Math.floor(Math.max(a.z, b.z) / ROAD_CELL);
    for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
      const k = ix * 100000 + iz;
      if (!ROAD_GRID.has(k)) ROAD_GRID.set(k, []);
      ROAD_GRID.get(k).push(seg);
    }
  }
}
/**
 * Nearest roads to (x, z) within `radius`: [{ road, dist, angle, horizontal }] sorted by distance, one entry per road
 * name. angle: the nearest segment's direction in [0, π) (atan2(dz, dx)); horizontal: it runs more east-west than
 * north-south.
 */
function nearestRoads(x, z, radius = 60) {
  const best = new Map();
  const ix0 = Math.floor((x - radius) / ROAD_CELL), ix1 = Math.floor((x + radius) / ROAD_CELL);
  const iz0 = Math.floor((z - radius) / ROAD_CELL), iz1 = Math.floor((z + radius) / ROAD_CELL);
  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
    const list = ROAD_GRID.get(ix * 100000 + iz);
    if (!list) continue;
    for (const s of list) {
      const dx = s.bx - s.ax, dz = s.bz - s.az;
      const L2 = dx * dx + dz * dz || 1e-9;
      const t = Math.max(0, Math.min(1, ((x - s.ax) * dx + (z - s.az) * dz) / L2));
      const d = Math.hypot(s.ax + t * dx - x, s.az + t * dz - z);
      if (d > radius) continue;
      const prev = best.get(s.r.name);
      if (!prev || d < prev.dist) {
        let angle = Math.atan2(dz, dx);
        if (angle < 0) angle += Math.PI;
        if (angle >= Math.PI) angle -= Math.PI;
        best.set(s.r.name, { road: s.r, dist: d, angle, horizontal: Math.abs(dx) > Math.abs(dz) });
      }
    }
  }
  return [...best.values()].sort((a, b) => a.dist - b.dist);
}

// ---------------------------------------------------------------------------------------------------------------------
// Blocks: every real curb island (raised sidewalk slab) with its lot rectangles inside the property line
//   poly: curb outline [{x, z}], rects: [[x0, x1, z0, z1], ...] building lots (axis-aligned), park: share covered by
//   parkland, parkName, rect: the island is an axis-aligned rectangle (none is in Poznań's unturned frame),
//   frames: lots laid out along the streets they front, [[θ, px, pz, rects], ...] (rects in a frame turned by θ about
//   (px, pz): world = p + R_y(θ)·(local − p)), or null
// ---------------------------------------------------------------------------------------------------------------------
const BLOCKS = GEO.blocks.map(([flat, rects, park, parkName, isRect, frames], id) => {
  const poly = toPts(flat);
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity, a = 0, cx = 0, cz = 0;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const p = poly[i], q = poly[j];
    minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
    const c = q.x * p.z - p.x * q.z;
    a += c; cx += (q.x + p.x) * c; cz += (q.z + p.z) * c;
  }
  a *= 0.5;
  const area = Math.abs(a);
  return {
    id, poly, rects, frames: frames || null, park, parkName, rect: !!isRect, area,
    minX, maxX, minZ, maxZ,
    cx: a ? cx / (6 * a) : (minX + maxX) / 2,
    cz: a ? cz / (6 * a) : (minZ + maxZ) / 2,
    median: Math.min(maxX - minX, maxZ - minZ) < 9
  };
});
// Spatial index of the blocks (64 m cells)
const BLOCK_CELL = 64;
const BLOCK_GRID = new Map();
for (const b of BLOCKS) {
  for (let ix = Math.floor(b.minX / BLOCK_CELL); ix <= Math.floor(b.maxX / BLOCK_CELL); ix++) {
    for (let iz = Math.floor(b.minZ / BLOCK_CELL); iz <= Math.floor(b.maxZ / BLOCK_CELL); iz++) {
      const k = ix * 100000 + iz;
      if (!BLOCK_GRID.has(k)) BLOCK_GRID.set(k, []);
      BLOCK_GRID.get(k).push(b);
    }
  }
}
/** The block (curb island) under (x, z), or null on the roadway / in the water */
function blockAt(x, z) {
  const list = BLOCK_GRID.get(Math.floor(x / BLOCK_CELL) * 100000 + Math.floor(z / BLOCK_CELL));
  if (!list) return null;
  for (const b of list) {
    if (x < b.minX || x > b.maxX || z < b.minZ || z > b.maxZ) continue;
    if (b.rect || pointInPoly(b.poly, x, z)) return b;
  }
  return null;
}
/** Blocks whose bounds overlap a rectangle */
function blocksInRect(minX, maxX, minZ, maxZ) {
  const out = new Set();
  for (let ix = Math.floor(minX / BLOCK_CELL); ix <= Math.floor(maxX / BLOCK_CELL); ix++) {
    for (let iz = Math.floor(minZ / BLOCK_CELL); iz <= Math.floor(maxZ / BLOCK_CELL); iz++) {
      const list = BLOCK_GRID.get(ix * 100000 + iz);
      if (list) for (const b of list) if (b.maxX > minX && b.minX < maxX && b.maxZ > minZ && b.minZ < maxZ) out.add(b);
    }
  }
  return [...out];
}

// ---------------------------------------------------------------------------------------------------------------------
// Districts (osiedla, GEO.districts) for building profiles, labels & the maps
// ---------------------------------------------------------------------------------------------------------------------
/** The osiedle name under (x, z) ('Stare Miasto', 'Jeżyce', 'Łazarz', …), or null outside every district ring */
function districtAt(x, z) {
  for (const d of DISTRICTS) {
    if (x < d.minX || x > d.maxX || z < d.minZ || z > d.maxZ) continue;
    if (pointInPoly(d.ring, x, z)) return d.name;
  }
  return null;
}
for (const b of BLOCKS) b.district = districtAt(b.cx, b.cz);

// ---------------------------------------------------------------------------------------------------------------------
// Landmarks (real footprints from OpenStreetMap, keyed by the curated name: { x, z, w, d, h, area, ring, ang })
// ---------------------------------------------------------------------------------------------------------------------
const LANDMARK_SITES = GEO.landmarks;
// The places the map and the location label name: [{ id, name, short, x, z, district }]
const site = (name, fallback) => LANDMARK_SITES[name] || fallback;
const CITY_LANDMARKS = [
  ['ratusz', 'Ratusz & Stary Rynek', 'Ratusz', 'Ratusz', 'Stare Miasto'],
  ['fara', 'Fara Poznańska', 'Fara', 'Fara', 'Stare Miasto'],
  ['zamekkrolewski', 'Zamek Królewski', 'Zamek Królewski', 'Zamek Królewski', 'Stare Miasto'],
  ['katedra', 'Archikatedra Poznańska', 'Katedra', 'Katedra', 'Ostrów Tumski'],
  ['brama', 'Brama Poznania ICHOT', 'Brama Poznania', 'Brama Poznania', 'Śródka'],
  ['zamek', 'Zamek Cesarski', 'Zamek Cesarski', 'Zamek Cesarski', 'Centrum'],
  ['baltyk', 'Bałtyk', 'Bałtyk', 'Bałtyk', 'Jeżyce'],
  ['okraglak', 'Okrąglak', 'Okrąglak', 'Okrąglak', 'Centrum'],
  ['teatr', 'Teatr Wielki', 'Teatr Wielki', 'Teatr Wielki', 'Centrum'],
  ['pomnik', 'Poznańskie Krzyże (Czerwiec 1956)', 'Krzyże 1956', 'Pomnik Czerwca 1956', 'Centrum'],
  ['dworzec', 'Poznań Główny', 'Poznań Główny', 'Poznań Główny', 'Łazarz'],
  ['browar', 'Stary Browar', 'Stary Browar', 'Stary Browar', 'Centrum'],
  ['iglica', 'Iglica MTP', 'Iglica', 'Iglica', 'Łazarz'],
  ['altum', 'Collegium Altum', 'Collegium Altum', 'Collegium Altum', 'Centrum'],
  ['andersia', 'Andersia Tower', 'Andersia', 'Andersia', 'Centrum']
].filter((r) => LANDMARK_SITES[r[3]]).map(([id, name, short, osm, district]) => {
  const s = site(osm, { x: 0, z: 0 });
  return { id, name, short, x: s.x, z: s.z, district };
});

// Street-level arrivals shared by every travel mode (docs/poznan-plan.md Phase 12.4). Heading 0 faces south (+z),
// PI north; each faces its landmark. The points sit on a roadway centreline (tests/teleports.test.cjs).
// `to`: a LANDMARK_SITES name or an { x, z } point to face.
const arrival = (x, z, to) => {
  const t = typeof to === 'string' ? LANDMARK_SITES[to] : to;
  return { x, z, heading: t ? Math.atan2(t.x - x, t.z - z) : 0 };
};
const TELEPORT_LOCATIONS = {
  // Zamkowa, where it opens onto the square's north-west corner: the one street with a clear view of the Ratusz
  rynek: arrival(-129.1, -60.2, 'Ratusz'),
  katedra: arrival(907.1, -246.5, 'Katedra'),
  zamek: arrival(-1049.7, 130.5, 'Zamek Cesarski'),
  baltyk: arrival(-1566.3, 76.3, 'Bałtyk'),
  // on Most Dworcowy, the deck over the tracks
  dworzec: arrival(-1518.5, 557.7, 'Poznań Główny'),
  teatr: arrival(-1191.7, -151.6, 'Teatr Wielki'),
  // the park's centre (52.4215 N, 16.9349 E) and the lake's widest point
  cytadela: arrival(-215.2, -1071.2, LL(16.9349, 52.4215)),
  malta: arrival(2507.1, 992.7, { x: 2690, z: 726 })
};
// Where a new session starts: ul. Święty Marcin in front of the Zamek Cesarski (CK Zamek). The street is divided here;
// this is the westbound carriageway on the castle's side, so the spawn faces west along it (13° north of due west)
const SPAWN = { x: -1049.7, z: 130.5, heading: Math.atan2(-16.1, -3.7) };

// Raised ground the player stands on, as {minX, maxX, minZ, maxZ, top} rects (none yet; landmarks may push theirs)
const RAISED_GROUND = [];

/**
 * Exact street / landmark / water name at any world (x, z), in the " · ", " & " and "near " format main.js
 * renderLocation splits on: "Landmark · Road & Road", "Warta · near Road", "Road & Road", "Road", or the district.
 */
function getLocationLabel(x, z) {
  // named roads only (OSM leaves many service and link roads unnamed)
  const named = (radius) => nearestRoads(x, z, radius).filter((r) => r.road.name);
  // two roads crossing at a real angle (> 30°) near the point
  const crossing = (near, within) => {
    const a = near[0];
    if (!a || a.dist > within) return null;
    const b = near.find((r) => {
      if (r === a || r.dist > within) return false;
      const d = Math.abs(r.angle - a.angle);
      return Math.min(d, Math.PI - d) > Math.PI / 6;
    });
    return b ? `${a.road.name} & ${b.road.name}` : null;
  };
  for (const lm of CITY_LANDMARKS) {
    if (Math.hypot(x - lm.x, z - lm.z) < 80) {
      const c = crossing(named(120), 120);
      return `${lm.name}${c ? ` · ${c}` : ''}`;
    }
  }
  const near = named(160);
  if (isWater(x, z) || (!isLand(x, z) && waterAt(x, z))) {
    const w = waterAt(x, z);
    const name = w && w.name ? w.name : 'Warta';
    return `${name}${near.length ? ` · near ${near[0].road.name}` : ''}`;
  }
  const c = crossing(near, 45);
  if (c) return c;
  if (near.length) return near[0].road.name;
  return districtAt(x, z) || 'Poznań';
}

// Keyboard shortcuts are ignored while typing into a form field (e.g. the map's street search box)
function isTypingInField(e) {
  return e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT');
}

// Search key for a name: lower case without diacritics, so "swiety" finds "Święty Marcin". NFD splits most accented
// letters into a base letter and combining marks, but ł/Ł are letters of their own with no decomposition.
function foldText(s) {
  return String(s).replace(/[łŁ]/g, (c) => (c === 'ł' ? 'l' : 'L')).normalize('NFD').replace(/\p{M}/gu, '').toLowerCase();
}

// Polish alphabetical order (ą after a, ł after l, ś after s, ż after ź), which also sorts plain English names right
const NAME_COLLATOR = new Intl.Collator('pl');
const compareNames = (a, b) => NAME_COLLATOR.compare(a, b);

// Upper case for map titles, in the same locale as the collator
const mapCaps = (s) => String(s).toLocaleUpperCase('pl');

// Counts in the UI, with Polish digit grouping ("12 345")
const formatCount = (n) => n.toLocaleString('pl');

// Traffic signal cycle shared by the signal heads (street-details.js) and the traffic (traffic.js), in seconds. A signal
// runs two groups (road-network.js sidesAndGroups): group 0, the widest road at the junction, and group 1, the other
// roads. The `avenue*` timings and `isAvenue` flags mean group 0 (names kept from the Manhattan grid, and audio reads
// `isAvenue`): it is green until avenueAmber, amber until avenueRed; group 1 is green from avenueRed until streetAmber,
// amber until the end of the cycle. Pedestrians cross with the traffic that runs parallel to them, stepping off only on
// the WALK, the first `walk` seconds of its green: long enough before the cross traffic's green for the slowest walker
// to get across the widest road.
const SIGNAL_TIMING = { cycle: 60, avenueAmber: 26, avenueRed: 30, streetAmber: 56, walk: 7 };

// 'green', 'amber' or 'red' for group 0 (isAvenue) or group 1 traffic at a given time
function signalPhase(time, isAvenue) {
  const { cycle, avenueAmber, avenueRed, streetAmber } = SIGNAL_TIMING;
  const t = ((time % cycle) + cycle) % cycle;
  if (isAvenue) return t < avenueAmber ? 'green' : t < avenueRed ? 'amber' : 'red';
  return t < avenueRed ? 'red' : t < streetAmber ? 'green' : 'amber';
}

// Do pedestrians walking alongside group 0 (isAvenue) or group 1 traffic have the WALK at a given time?
function walkSignal(time, isAvenue) {
  const { cycle, avenueRed, walk } = SIGNAL_TIMING;
  const t = (((time - (isAvenue ? 0 : avenueRed)) % cycle) + cycle) % cycle;
  return t < walk;
}

